type NCrossValidations struct {
	Auto   *AutoNCrossValidations   `json:"auto,omitempty"`
	Custom *CustomNCrossValidations `json:"custom,omitempty"`
}

// MarshalJSON defers JSON marshaling to the first non-nil property, because NCrossValidations represents a discriminated union (JSON OneOf)
func (validations NCrossValidations) MarshalJSON() ([]byte, error) {
	if validations.Auto != nil {
		return json.Marshal(validations.Auto)
	}

	if validations.Custom != nil {
		return json.Marshal(validations.Custom)
	}

	return nil, nil
}

// UnmarshalJSON unmarshals the NCrossValidations
func (validations *NCrossValidations) UnmarshalJSON(data []byte) error {
	var rawJson map[string]interface{}
	err := json.Unmarshal(data, &rawJson)
	if err != nil {
		return err
	}
	discriminator := rawJson["mode"]
	if discriminator == "Auto" {
		validations.Auto = &AutoNCrossValidations{}
		return json.Unmarshal(data, validations.Auto)
	}
	if discriminator == "Custom" {
		validations.Custom = &CustomNCrossValidations{}
		return json.Unmarshal(data, validations.Custom)
	}

	// No error
	return nil
}

